corporate_design.toad_component_blueprint:
canvas {
  size: 920px 560px;
  fill: #F1F5F9;
  font-family: "Space Grotesk, sans-serif";
}

>red = #E11D48;
>dark = #0F172A;

rect #trainCard {
  at: center of canvas;
  size: 820px 460px;
  fill: #FFFFFF;
  stroke: >red;
  stroke-width: 2px;
  radius: 12px;
}

text #trainHeader {
  at: top left of #trainCard offset 36px 36px;
  content: "AEROTRAIN // PARIS - BERLIN IN 4 STUNDEN";
  font-size: 14px;
  font-weight: 700;
  color: >red;
}

text #trainTitle {
  at: below #trainHeader offset 16px;
  content: "Europas schnellstes Schienennetz mit 350 km/h";
  font-size: 32px;
  font-weight: 700;
  color: >dark;
}
